style.css:
@-moz-document domain("chat.openai.com") {
/* Background */
body, .app {
    background-color: #ffe6f2 !important; /* Soft pastel pink */
}

/* Main Chat Window */
div[class*="react-scroll-to-bottom"] {
    background-color: #fff5fa !important; /* Lighter pastel pink */
}

/* Sidebar */
nav, .dark .bg-gray-900 {
    background-color: #ffdded !important; /* Slightly darker pastel */
}

/* Text */
h1, h2, h3, h4, h5, h6, p, span, div, a, button {
    color: #ff1493 !important; /* Hot pink text */
}

/* Chat Messages */
div[class*="markdown"] {
    background: #fff0f6 !important; /* Light pink bubble */
    border-radius: 12px;
    padding: 10px;
    margin-bottom: 8px;
}

/* Input Box */
textarea {
    background-color: #fff0f6 !important;
    border: 2px solid #ff99c8 !important;
    color: #ff1493 !important;
}

/* Buttons */
button {
    background-color: #ff99c8 !important; /* Light pink */
    border: none;
    color: white !important;
    font-weight: bold;
    padding: 8px 16px;
    border-radius: 8px;
}

/* Button Hover */
button:hover {
    background-color: #ff6fa6 !important;
}

/* Headers with Bows ? */
h1::before, h2::before {
    content: "? ";
}

h1::after, h2::after {
    content: " ?";
}

/* Scrollbar */
::-webkit-scrollbar {
    width: 10px;
}

::-webkit-scrollbar-thumb {
    background: #ff99c8 !important;
    border-radius: 5px;
}

::-webkit-scrollbar-track {
    background: #ffe6f2 !important;
}
}
